<?= $this->extend('admin/layout') ?><?= $this->section('content') ?><form class="filters" method="get"><label>Status<select name="status"><option value="">All</option><?php foreach(['pending','under_review','resolved','rejected'] as $s):?><option <?= $status===$s?'selected':'' ?>><?= esc($s) ?></option><?php endforeach ?></select></label><button>Filter</button></form><div class="table-wrap"><table><thead><tr><th>ID</th><th>Student ID</th><th>Name</th><th>Status</th><th>Submitted</th></tr></thead><tbody><?php foreach($requests as $r):?><tr><td><a href="<?= site_url('admin/verification-requests/'.$r['id']) ?>">#<?= (int)$r['id'] ?></a></td><td><?= esc($r['student_id']) ?></td><td><?= esc($r['full_name']) ?></td><td><?= esc($r['status']) ?></td><td><?= esc($r['created_at']) ?></td></tr><?php endforeach ?></tbody></table></div><?= $pager->links() ?><?= $this->endSection() ?>
